public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0 || start == null || end == null || paths == null || start.length == 0 || end.length == 0) {
            return "cannot be travelled";
        }

        int startId = start[0];
        int endId = end[0];

        if (startId < 0 || startId >= n || endId < 0 || endId >= n) {
            return "cannot be travelled";
        }

        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int[] p : paths) {
            if (p == null || p.length < 2) {
                continue;
            }
            int a = p[0];
            int b = p[1];
            if (a < 0 || a >= n || b < 0 || b >= n) {
                continue;
            }
            adj.get(a).add(b);
            adj.get(b).add(a);
        }

        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(startId);
        visited[startId] = true;

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            if (cur == endId) {
                return "can be travelled";
            }
            for (int next : adj.get(cur)) {
                if (!visited[next]) {
                    visited[next] = true;
                    queue.add(next);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

