  // A boomerang is a set of three points that are all distinct from each other and do not lie in a straight line.
  // To check this, we can use the slope formula: (y2 - y1) / (x2 - x1) and compare the slope of two lines
  // If the slopes are equal, it means the points are collinear and hence cannot form a boomerang.

  int x1 = points[0][0], y1 = points[0][1];
  int x2 = points[1][0], y2 = points[1][1];
  int x3 = points[2][0], y3 = points[2][1];

  // Calculate the slopes of line segment formed by (point1, point2) and (point1, point3).
  // To avoid division by zero, we'll cross-multiply to compare the slopes.
  int slope1 = (y2 - y1) * (x3 - x1);
  int slope2 = (y3 - y1) * (x2 - x1);

  // The points form a boomerang if the slopes are not equal.
  return slope1 != slope2;
}

